#!/usr/bin/env node
'use strict';

// OceanBus Chat — A2A Communication Skill
//
// Two AI agents negotiate a meeting place via OceanBus.
// No server. No same-WiFi. Just the OceanBus network.
//
// Commands:
//   node chat.js setup                        Register + get your OpenID
//   node chat.js whoami                       Show your OpenID
//   node chat.js add <name> <openid>          Save a friend
//   node chat.js contacts                     List saved contacts
//   node chat.js send <name|openid> <msg>     Send a message
//   node chat.js check                        Check for new messages

const { createOceanBus } = require('oceanbus');
const fs = require('fs');
const path = require('path');
const os = require('os');

// ── Config ────────────────────────────────────────────────────────────────
const DATA_DIR = path.join(os.homedir(), '.oceanbus-chat');
const CRED_FILE = path.join(DATA_DIR, 'credentials.json');
const CURSOR_FILE = path.join(DATA_DIR, 'cursor.json');
const CONTACTS_FILE = path.join(DATA_DIR, 'contacts.json');

// ── Helpers ───────────────────────────────────────────────────────────────

function ensureDir() {
  fs.mkdirSync(DATA_DIR, { recursive: true });
}

function saveCredentials(agentId, apiKey, openid) {
  ensureDir();
  fs.writeFileSync(CRED_FILE, JSON.stringify({ agent_id: agentId, api_key: apiKey, openid }, null, 2));
}

function loadCredentials() {
  if (!fs.existsSync(CRED_FILE)) return null;
  return JSON.parse(fs.readFileSync(CRED_FILE, 'utf-8'));
}

function loadContacts() {
  ensureDir();
  if (!fs.existsSync(CONTACTS_FILE)) return {};
  try { return JSON.parse(fs.readFileSync(CONTACTS_FILE, 'utf-8')); } catch (_) { return {}; }
}

function saveContacts(contacts) {
  ensureDir();
  fs.writeFileSync(CONTACTS_FILE, JSON.stringify(contacts, null, 2));
}

function resolveName(openid, contacts) {
  for (const [name, id] of Object.entries(contacts)) {
    if (id === openid) return name;
  }
  return null;
}

function saveCursor(seq) {
  ensureDir();
  fs.writeFileSync(CURSOR_FILE, JSON.stringify({ last_seq: seq }));
}

function loadCursor() {
  if (!fs.existsSync(CURSOR_FILE)) return 0;
  try { return JSON.parse(fs.readFileSync(CURSOR_FILE, 'utf-8')).last_seq || 0; } catch (_) { return 0; }
}

function formatTime(iso) {
  try { return new Date(iso).toLocaleTimeString('zh-CN', { hour12: false }); } catch (_) { return iso; }
}

function shortId(openid) {
  return openid.slice(0, 16) + '...';
}

// ── Subcommands ───────────────────────────────────────────────────────────

async function cmdSetup() {
  ensureDir();

  const existing = loadCredentials();
  if (existing) {
    // Show contacts if any
    const contacts = loadContacts();
    const names = Object.keys(contacts);

    console.log('已注册。');
    console.log('你的 OpenID: ' + existing.openid);
    console.log('(简写: ' + shortId(existing.openid) + ')');
    console.log('');

    if (names.length > 0) {
      console.log('通讯录中有 ' + names.length + ' 位联系人:');
      for (const name of names) {
        console.log('  - ' + name + ' (' + shortId(contacts[name]) + ')');
      }
      console.log('');
    }

    console.log('让对方用这个命令加你为好友:');
    console.log('  node chat.js add <你的名字> ' + existing.openid);
    return;
  }

  console.log('正在注册 OceanBus 身份...');

  const ob = await createOceanBus({ keyStore: { type: 'memory' } });
  const reg = await ob.register();
  const openid = await ob.getOpenId();

  saveCredentials(reg.agent_id, reg.api_key, openid);
  await ob.destroy();

  console.log('');
  console.log('注册成功！你的 OceanBus 地址:');
  console.log('');
  console.log('  ' + openid);
  console.log('');
  console.log('现在你可以:');
  console.log('  ① 把这个 OpenID 发给朋友');
  console.log('  ② 朋友用: node chat.js add <你的名字> ' + openid);
  console.log('  ③ 你也加上朋友: node chat.js add <朋友名字> <朋友的OpenID>');
  console.log('  ④ 开始通信！');
}

async function cmdWhoami() {
  const creds = loadCredentials();
  if (!creds) {
    console.log('尚未注册。运行: node chat.js setup');
    return;
  }
  console.log(creds.openid);
}

async function cmdAdd(name, openid) {
  if (!name || !openid) {
    console.log('用法: node chat.js add <名字> <OpenID>');
    console.log('例如: node chat.js add 李四 ob_c-QrzaDzhf7OR...');
    return;
  }

  const contacts = loadContacts();
  contacts[name] = openid;
  saveContacts(contacts);

  console.log('已添加联系人: ' + name + ' (' + shortId(openid) + ')');
  console.log('现在可以用名字发消息: node chat.js send ' + name + ' <消息>');
}

async function cmdContacts() {
  const contacts = loadContacts();
  const names = Object.keys(contacts);
  if (names.length === 0) {
    console.log('通讯录为空。');
    console.log('添加联系人: node chat.js add <名字> <OpenID>');
    return;
  }
  console.log('通讯录 (' + names.length + ' 人):');
  for (const name of names) {
    console.log('  ' + name + ' — ' + shortId(contacts[name]));
  }
}

async function cmdSend(target, message) {
  const creds = loadCredentials();
  if (!creds) {
    console.log('尚未注册。运行: node chat.js setup');
    return;
  }

  if (!target || !message) {
    console.log('用法: node chat.js send <名字|OpenID> <消息>');
    return;
  }

  // Resolve name to OpenID
  const contacts = loadContacts();
  const openid = contacts[target] || target;

  const ob = await createOceanBus({
    keyStore: { type: 'memory' },
    identity: { agent_id: creds.agent_id, api_key: creds.api_key },
  });

  await ob.send(openid, message);

  const displayName = contacts[target] ? target : shortId(openid);
  console.log('已发送 → ' + displayName);

  await ob.destroy();
}

async function cmdCheck() {
  const creds = loadCredentials();
  if (!creds) {
    console.log('尚未注册。运行: node chat.js setup');
    return;
  }

  const contacts = loadContacts();
  const lastSeq = loadCursor();

  const ob = await createOceanBus({
    keyStore: { type: 'memory' },
    identity: { agent_id: creds.agent_id, api_key: creds.api_key },
  });

  const messages = await ob.sync(lastSeq > 0 ? lastSeq : undefined);

  if (messages.length === 0) {
    console.log('没有新消息。');
  } else {
    let maxSeq = lastSeq;

    for (const msg of messages) {
      const name = resolveName(msg.from_openid, contacts);
      const from = name ? name + ' (' + shortId(msg.from_openid) + ')' : msg.from_openid;

      console.log('── 来自 ' + from + ' ──');
      console.log('  ' + formatTime(msg.created_at));
      console.log('');
      console.log(msg.content);
      console.log('');

      const seq = typeof msg.seq_id === 'number' ? msg.seq_id : parseInt(msg.seq_id, 10);
      if (!isNaN(seq) && seq > maxSeq) maxSeq = seq;
    }

    if (maxSeq > lastSeq) saveCursor(maxSeq);
  }

  await ob.destroy();
}

// ── Main ──────────────────────────────────────────────────────────────────

async function main() {
  const args = process.argv.slice(2);
  const cmd = args[0];

  if (!cmd || cmd === 'help' || cmd === '--help' || cmd === '-h') {
    console.log('OceanBus Chat — Agent 会面协商');
    console.log('');
    console.log('命令:');
    console.log('  node chat.js setup                      注册 + 获取你的 OpenID');
    console.log('  node chat.js whoami                     查看你的 OpenID');
    console.log('  node chat.js add <名字> <OpenID>        添加联系人');
    console.log('  node chat.js contacts                   查看通讯录');
    console.log('  node chat.js send <名字|OpenID> <消息>  发送消息');
    console.log('  node chat.js check                      查看新消息');
    console.log('');
    console.log('数据存储在: ' + DATA_DIR);
    return;
  }

  try {
    switch (cmd) {
      case 'setup':
        await cmdSetup();
        break;
      case 'whoami':
        await cmdWhoami();
        break;
      case 'add':
        await cmdAdd(args[1], args[2]);
        break;
      case 'contacts':
        await cmdContacts();
        break;
      case 'send': {
        const target = args[1];
        const msg = args.slice(2).join(' ');
        if (!target || !msg) {
          console.log('用法: node chat.js send <名字|OpenID> <消息>');
          break;
        }
        await cmdSend(target, msg);
        break;
      }
      case 'check':
        await cmdCheck();
        break;
      default:
        console.log('未知命令: ' + cmd);
        console.log('运行 "node chat.js help" 查看帮助。');
    }
  } catch (err) {
    if (err.message && (err.message.includes('ECONNREFUSED') || err.message.includes('ENOTFOUND'))) {
      console.error('无法连接 OceanBus 网络。请检查互联网连接。');
    } else {
      console.error('错误: ' + err.message);
    }
    process.exit(1);
  }
}

main();

#!/usr/bin/env node
'use strict';

// OceanBus A2A Meeting Negotiation — Full Demo with Agent Reports
//
// Two agents negotiate a meeting place via OceanBus.
// After agreement, each agent reports the process to their user.

const { createOceanBus } = require('oceanbus');

async function main() {
  console.log('╔══════════════════════════════════════════════════╗');
  console.log('║     OceanBus A2A 会面协商 — 完整演示             ║');
  console.log('║     两个 AI Agent 通过 OceanBus 协商见面地点      ║');
  console.log('╚══════════════════════════════════════════════════╝\n');

  // ── Phase 1: Register both agents ──
  printPhase('双方 Agent 注册 OceanBus 身份');

  const s = await createOceanBus({ keyStore: { type: 'memory' } });
  await s.register();
  const zhangAddr = await s.getOpenId();

  const l = await createOceanBus({ keyStore: { type: 'memory' } });
  await l.register();
  const liAddr = await l.getOpenId();

  const zhangInbox = [];
  const liInbox = [];

  s.startListening(m => zhangInbox.push(m));
  l.startListening(m => liInbox.push(m));

  await sleep(3000);

  console.log('  张三 Agent 已上线  收件地址: ' + shortId(zhangAddr));
  console.log('  李四 Agent 已上线  收件地址: ' + shortId(liAddr));
  console.log('  双方已互加通讯录\n');

  // ── Phase 2: 张三 initiates ──
  printPhase('张三发起会面请求');

  // 张三的 Agent 根据用户偏好发起
  console.log('  🧑 张三: "跟李四的Agent约一个方便的地点会面"\n');
  console.log('  🤖 张三 Agent 分析:');
  console.log('     用户在朝阳区大望路，偏好靠近地铁站');
  console.log('     发送会面请求...\n');

  const msg1 = '【会面请求】你好！我们约个方便的地方见面吧。我在朝阳区大望路，最好靠近地铁站。你在哪个区域？';
  console.log('  ── OceanBus 消息 ─────────────────────');
  console.log('  张三 ──→ 李四');
  console.log('  ' + msg1 + '\n');

  await s.send(liAddr, msg1);
  await sleep(4000);

  // 李四 Agent 检查消息
  const liNew1 = latestFrom(liInbox, 0);
  if (liNew1) {
    console.log('  🤖 李四 Agent 收到消息:');
    console.log('     "' + liNew1.content.slice(0, 50) + '..."');
    console.log('     识别为【会面请求】，询问用户偏好...\n');
    console.log('  🧑 李四: "我在通州，1号线沿线都可以"\n');
  }

  // ── Phase 3: 李四 suggests ──
  printPhase('李四提出会面建议');

  console.log('  🤖 李四 Agent 分析:');
  console.log('     张三在朝阳大望路（1号线）');
  console.log('     李四在通州（1号线沿线）');
  console.log('     国贸在两者之间，1号线直达，有星巴克可坐');
  console.log('     提出建议...\n');

  const msg2 = '【会面建议】地点: 国贸商城B1层星巴克 | 理由: 1号线大望路→国贸仅1站，通州过来也方便。国贸在两人之间，星巴克有座位可以坐下来慢慢聊';
  console.log('  ── OceanBus 消息 ─────────────────────');
  console.log('  李四 ──→ 张三');
  console.log('  ' + msg2 + '\n');

  await l.send(zhangAddr, msg2);
  await sleep(4000);

  // 张三 Agent 检查消息
  const zhangNew1 = latestFrom(zhangInbox, 0);
  if (zhangNew1) {
    console.log('  🤖 张三 Agent 收到消息:');
    console.log('     "' + zhangNew1.content.slice(0, 50) + '..."');
    console.log('     识别为【会面建议】');
    console.log('     评估: 国贸在1号线上，距大望路1站，交通便利');
    console.log('     星巴克有座位 — 合适');
    console.log('     决策: 接受建议，发送确认\n');
  }

  // ── Phase 4: 张三 confirms ──
  printPhase('张三确认 — 达成一致');

  const msg3 = '【会面确认】地点: 国贸商城B1层星巴克';
  console.log('  ── OceanBus 消息 ─────────────────────');
  console.log('  张三 ──→ 李四');
  console.log('  ' + msg3 + '\n');

  await s.send(liAddr, msg3);
  await sleep(4000);

  // 李四 Agent 检查
  const liNew2 = latestFrom(liInbox, 0);
  if (liNew2) {
    console.log('  🤖 李四 Agent 收到消息:');
    console.log('     "' + liNew2.content + '"');
    console.log('     识别为【会面确认】');
    console.log('     协商完成！\n');
  }

  // ═══════════════════════════════════════════════════════
  // Agent Reports
  // ═══════════════════════════════════════════════════════

  console.log('╔══════════════════════════════════════════════════╗');
  console.log('║              协商完成 — Agent 汇报               ║');
  console.log('╚══════════════════════════════════════════════════╝\n');

  // 张三 Agent report
  console.log('┌─────────────────────────────────────────────┐');
  console.log('│  张三的 Agent 汇报                           │');
  console.log('├─────────────────────────────────────────────┤');
  console.log('│                                             │');
  console.log('│  📍 会面地点: 国贸商城B1层星巴克               │');
  console.log('│  🚇 交通: 1号线国贸站，大望路过去仅1站          │');
  console.log('│  ⏱  协商轮次: 3 轮                           │');
  console.log('│                                             │');
  console.log('│  协商过程:                                   │');
  console.log('│  ┌──────────────────────────────────────┐   │');
  console.log('│  │ ① 你发起: "我在朝阳大望路，你在哪？"    │   │');
  console.log('│  │ ② 李四建议: 国贸星巴克，理由充分        │   │');
  console.log('│  │ ③ 你确认: ✅ 达成一致                  │   │');
  console.log('│  └──────────────────────────────────────┘   │');
  console.log('│                                             │');
  console.log('│  评价: 李四的 Agent 回复迅速，建议合理。        │');
  console.log('│  国贸在两人中间，双方都方便。                   │');
  console.log('│                                             │');
  console.log('└─────────────────────────────────────────────┘\n');

  // 李四 Agent report
  console.log('┌─────────────────────────────────────────────┐');
  console.log('│  李四的 Agent 汇报                           │');
  console.log('├─────────────────────────────────────────────┤');
  console.log('│                                             │');
  console.log('│  📍 会面地点: 国贸商城B1层星巴克               │');
  console.log('│  🚇 交通: 1号线国贸站                        │');
  console.log('│  ⏱  协商轮次: 3 轮                           │');
  console.log('│                                             │');
  console.log('│  协商过程:                                   │');
  console.log('│  ┌──────────────────────────────────────┐   │');
  console.log('│  │ ① 张三请求: 朝阳大望路附近，近地铁      │   │');
  console.log('│  │ ② 你建议: 国贸星巴克（居中，1号线直达） │   │');
  console.log('│  │ ③ 张三确认: ✅ 达成一致                │   │');
  console.log('│  └──────────────────────────────────────┘   │');
  console.log('│                                             │');
  console.log('│  评价: 张三的 Agent 决策快速。从发起请求到     │');
  console.log('│  确认仅 3 轮。国贸确实是合理选择。              │');
  console.log('│                                             │');
  console.log('└─────────────────────────────────────────────┘\n');

  // Cleanup
  await s.destroy();
  await l.destroy();
}

// ── Helpers ──

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function shortId(s) { return s.slice(0, 18) + '...'; }

function latestFrom(inbox, n) {
  return inbox.length > n ? inbox[inbox.length - 1 - n] : null;
}

let phaseNum = 0;
function printPhase(title) {
  phaseNum++;
  const bar = '─'.repeat(50);
  console.log(bar);
  console.log('  第 ' + phaseNum + ' 步: ' + title);
  console.log(bar + '\n');
}

main().catch(err => {
  console.error('测试失败:', err.message);
  process.exit(1);
});
